     9	    /**
    10	     * Returns the index of {@code target} in an ascending sorted array, or
    11	     * {@link #NOT_FOUND} when the target is absent.
    12	     */
    13	    public static int binarySearch(int[] sortedNumbers, int target) {
    14	        Objects.requireNonNull(sortedNumbers, "sortedNumbers must not be null");
    15	
    16	        int left = 0;
    17	        int right = sortedNumbers.length - 1;
    18	
    19	        while (left <= right) {
    20	            int middle = midpoint(left, right);
    21	            int comparison = Integer.compare(sortedNumbers[middle], target);
    22	
    23	            if (comparison == 0) {
    24	                return middle;
    25	            }
    26	
    27	            if (comparison < 0) {
    28	                left = middle + 1;
    29	            } else {
    30	                right = middle - 1;
    31	            }
    32	        }
    33	
    34	        return NOT_FOUND;
    35	    }
    36	
    37	    private static int midpoint(int left, int right) {
    38	        return left + (right - left) / 2;
    39	    }
